pub struct AdminUserApiUserIdApi<'a> {
    stream: &'a Arc<Mutex<TcpStream>>,
    #[allow(clippy::type_complexity)]
    customs: &'a Vec<
        Box<dyn Fn() -> Result<Box<dyn std::any::Any>, Box<dyn std::error::Error>> + Send + Sync>,
    >,
}

impl<'a> AdminUserApiUserIdApi<'a> {}
